// Simulación de datos para pruebas dentro de n8n
return {
  json: {
    body: {
      consulta: "Analiza los productos con stock crítico y sugiere orden de compra",
      contexto: {
        modo: "Prueba manual en n8n",
        tienda: "Cafetería Aroma & Código"
      }
    }
  }
};

// 1. VALIDACIÓN DE ENTRADA (Acepta datos del Webhook o del botón Test)
const raw = $json.body || $json;
const consulta = raw.consulta || (typeof raw === 'string' ? raw : '');

if (!consulta || typeof consulta !== 'string' || consulta.trim() === '') {
  return {
    json: {
      esValido: false,
      error: 'La consulta es obligatoria y debe ser un texto válido.'
    }
  };
}

return {
  json: {
    esValido: true,
    consulta: consulta.trim(),
    contexto: raw.contexto || {}
  }
};

// 3. AGENTE IA DE NEGOCIO & FORMATEO DE RESPUESTA
const consulta = $('Validar Consulta').item.json.consulta.toLowerCase();

// Obtener los productos reales de la API
let items = $input.all().map(i => i.json);
let productos = Array.isArray(items[0]) ? items[0] : items;

// Filtrar productos con stock <= stock_minimo
const criticos = productos.filter(p => p.stock !== undefined && p.stock_minimo !== undefined && p.stock <= p.stock_minimo);

let textoRespuesta = '';

if (consulta.includes('compra') || consulta.includes('reabastecimiento') || consulta.includes('stock')) {
  if (criticos.length === 0) {
    textoRespuesta = '📋 **INFORME DE REABASTECIMIENTO:**\n\nTodos los productos del inventario cuentan con existencias suficientes. No se requieren compras de urgencia.';
  } else {
    const lineas = criticos.map(p => 
      `- **${p.nombre}** (Categoría: ${p.categoria_nombre || 'General'})\n  Existencias: **${p.stock} unid.** | Mínimo: ${p.stock_minimo}\n  👉 *Recomendación:* Comprar lote de **${(p.stock_minimo * 3) - p.stock} unidades** para garantizar 10 días de venta.`
    ).join('\n\n');

    textoRespuesta = `📋 **PLAN DE REABASTECIMIENTO PRIORITARIO:**\n\nSe detectaron ${criticos.length} productos con inventario crítico:\n\n${lineas}\n\n💡 *Consejo Logístico:* Contactar al proveedor temprano para asegurar la entrega de repostería fresca.`;
  }
} else if (consulta.includes('promo') || consulta.includes('combo') || consulta.includes('venta')) {
  textoRespuesta = `🏷️ **PROPUESTA DE COMBOS Y PROMOCIONES:**\n\n1. **Combo Despertar ($5.25 - 15% OFF):**\n   - Café Americano 12oz + Croissant de Mantequilla recién horneado.\n   - *Objetivo:* Agilizar la salida de repostería matutina.\n\n2. **Dúo Dulce Tarde ($6.50 Especial):**\n   - Cappuccino Italiano 8oz + Muffin de Arándanos.\n   - *Objetivo:* Elevar el ticket promedio por encima de los $6.00.`;
} else {
  textoRespuesta = `☕ **ASISTENTE DE CAFETERÍA 'AROMA & CÓDIGO':**\n\nConsulta procesada: "${$('Validar Consulta').item.json.consulta}".\n\n- Total productos activos: **${productos.length}**\n- Productos en stock crítico: **${criticos.length}**\n\nPuedes consultarme: "Sugerir orden de compra" o "Proponer combos del día".`;
}

// CONTRATO ESTRICTO: { ok: true, data: { ... }, error: null }
return {
  json: {
    ok: true,
    data: {
      mensaje: textoRespuesta,
      timestamp: new Date().toISOString(),
      agente: 'Agente IA Autónomo - Aroma & Código'
    },
    error: null
  }
};
